script:
(function () {
  'use strict';
  // Retirement nest egg from a withdrawal-rate rule.
  //   income gap (today's $)  = desired income - other income (not below 0)
  //   first-year withdrawal   = gap / (1 - tax rate) x (1 + inflation)^years to retirement
  //   nest egg needed         = first-year withdrawal / withdrawal rate
  //   today's savings grow to = savings x (1 + return)^years
  //   monthly saving          = shortfall x i / ((1 + i)^(12 x years) - 1), i = (1 + return)^(1/12) - 1,
  //                             deposits at the end of each month (shortfall / months when return is 0)
  //   lasts about             = years until a start-of-year withdrawal rising with inflation exceeds
  //                             the balance, the rest earning the retirement return (fractional last year)
  // Checked in Node (scratch tests): $60,000 wanted - $24,000 other, 22 years at 3% inflation ->
  //   first withdrawal $36,000 x 1.03^22 = $68,979.72; at 4% -> $1,724,493.07 ($900,000 today);
  //   $150,000 at 6% for 22 years -> $540,530.61; monthly saving $2,213.53, and a month-by-month
  //   loop of that deposit reaches the $1,183,962.46 shortfall exactly. 4% with 0% return and 0%
  //   inflation lasts exactly 25 years; 4% at 5% return / 3% inflation lasts 33.6 years (33 full
  //   withdrawals have a present value of 24.67 first-year withdrawals out of 25, by the
  //   growing-annuity-due closed form). A 20% tax rate grosses $36,000 up to $45,000.
  var MAX_YEARS = 100;
  var RATES_TABLE = [3, 3.5, 4, 4.5, 5, 5.5, 6];

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return isFinite(x) ? moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x) : '–'; } };
  var one = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });

  function monthlySaving(shortfall, annualRate, years) {
    if (shortfall <= 0) return 0;
    if (years <= 0) return NaN;
    var i = Math.pow(1 + annualRate, 1 / 12) - 1, m = years * 12;
    return i === 0 ? shortfall / m : shortfall * i / (Math.pow(1 + i, m) - 1);
  }

  // Years a balance lasts with start-of-year withdrawals of first x (1 + inflation)^k; null = 100+.
  function lasts(balance, first, postRate, inflation) {
    if (first <= 0) return null;
    var b = balance;
    for (var k = 0; k < MAX_YEARS; k++) {
      var w = first * Math.pow(1 + inflation, k);
      if (w > b + 1e-9) return k + b / w;
      b = (b - w) * (1 + postRate);
    }
    return null;
  }

  function nestEgg(p) {
    var n = p.retireAge - p.age;
    var infl = Math.pow(1 + p.inflation, n);
    var gapToday = Math.max(0, p.income - p.other);
    var grossToday = gapToday / (1 - p.tax);
    var first = grossToday * infl;
    var projected = p.savings * Math.pow(1 + p.preRate, n);
    function at(rate) {
      var target = first / rate;
      var shortfall = target - projected;
      return {
        rate: rate, target: target, real: target / infl, shortfall: shortfall,
        monthly: monthlySaving(shortfall, p.preRate, n), lasts: lasts(target, first, p.postRate, p.inflation)
      };
    }
    var main = at(p.rate);
    main.n = n; main.first = first; main.gapToday = gapToday; main.projected = projected; main.at = at;
    return main;
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function yearsText(y) { return y === null ? MAX_YEARS + '+ years' : one.format(y) + ' years'; }

  function update() {
    var age = Math.round(num('neAge')), retireAge = Math.round(num('neRetireAge')), income = num('neIncome'),
        other = num('neOther'), rate = num('neRate'), inflation = num('neInflation'), savings = num('neSavings'),
        preRate = num('nePreRate'), tax = num('neTax'), postRate = num('nePostRate');
    var error = document.getElementById('neError');
    var bad = [age, retireAge, income, other, rate, inflation, savings, preRate, tax, postRate].some(isNaN) ||
              age < 16 || age > 99 || retireAge < age || retireAge > 100 || income < 0 || other < 0 ||
              rate < 0.5 || rate > 20 || inflation < 0 || inflation > 20 || savings < 0 ||
              preRate < 0 || preRate > 30 || postRate < 0 || postRate > 30 || tax < 0 || tax > 60;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Check your ages (retirement age at or above current age, up to 100), use non-negative amounts, ' +
                          'a withdrawal rate from 0.5% to 20%, returns up to 30%, inflation up to 20% and a tax rate up to 60%.';
      return;
    }
    var p = { age: age, retireAge: retireAge, income: income, other: other, rate: rate / 100, inflation: inflation / 100,
              savings: savings, preRate: preRate / 100, tax: tax / 100, postRate: postRate / 100 };
    var r = nestEgg(p);
    set('neTargetLabel', 'Nest egg needed at age ' + retireAge);
    set('neTarget', money.format(r.target));
    set('neTargetReal', money.format(r.real));
    set('neMonthly', r.shortfall <= 0 ? money.format(0) : r.n > 0 ? money.format(r.monthly) : 'Retiring now');
    set('neFirstLabel', 'First-year withdrawal at age ' + retireAge + (tax > 0 ? ' (before tax)' : ''));
    set('neFirst', money.format(r.first));
    set('neGapToday', money.format(r.gapToday));
    set('neProjectedLabel', "Today's savings grow to (age " + retireAge + ')');
    set('neProjected', money.format(r.projected));
    set('neShortLabel', r.shortfall > 0 ? 'Still to save' : 'Ahead of target by');
    set('neShort', money.format(Math.abs(r.shortfall)));
    set('neLasts', r.first > 0 ? yearsText(r.lasts) : 'Not needed');
    var summary;
    if (r.gapToday === 0) summary = 'Your other income already covers the income you want, so you do not need a nest egg for it. ' +
      'Savings would still help with taxes, health costs and surprises.';
    else if (r.shortfall <= 0) summary = 'Without adding anything, your current savings are on track to beat this target by ' +
      money.format(-r.shortfall) + ' at a ' + one.format(preRate) + '% return.';
    else if (r.n > 0) summary = 'Saving about ' + money.format(r.monthly) + ' a month from now until age ' + retireAge +
      ' (' + money.format(r.monthly * 12) + ' a year), on top of the savings you have, would reach the target.';
    else summary = 'You are at your retirement age, so the gap of ' + money.format(r.shortfall) +
      ' would have to be closed by spending less, working longer or a lower withdrawal rate.';
    set('neSummary', summary);

    var rates = RATES_TABLE.slice();
    if (rates.indexOf(rate) < 0) { rates.push(rate); rates.sort(function (a, b) { return a - b; }); }
    var body = document.getElementById('neGrid');
    body.textContent = '';
    rates.forEach(function (rt) {
      var x = r.at(rt / 100);
      var tr = document.createElement('tr');
      var cells = [one.format(rt) + '%' + (rt === rate ? ' (yours)' : ''), money.format(x.target), money.format(x.real),
                   x.shortfall <= 0 ? money.format(0) : r.n > 0 ? money.format(x.monthly) : '–',
                   r.first > 0 ? yearsText(x.lasts) : '–'];
      cells.forEach(function (v, idx) {
        var td = document.createElement(idx === 0 ? 'th' : 'td');
        if (idx === 0) td.setAttribute('scope', 'row');
        td.textContent = v;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('neForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
